value.string:
{\n
  "type": "object",\n
  "additionalProperties": true,\n
  "description": "Two-way diff between the repository and the installed ERP5 representation, plus safety.",\n
  "properties": {\n
    "business_template": {\n
      "type": "string"\n
    },\n
    "repository_to_zodb": {\n
      "type": "object"\n
    },\n
    "zodb_to_repository": {\n
      "type": [\n
        "object",\n
        "null"\n
      ]\n
    },\n
    "conflicts": {\n
      "type": "array",\n
      "items": {\n
        "type": "string"\n
      }\n
    },\n
    "update_from_repository_safe": {\n
      "type": "boolean"\n
    },\n
    "export_to_repository_safe": {\n
      "type": "boolean"\n
    }\n
  }\n
}

{
 "type": "object",
 "additionalProperties": false,
 "required": ["business_template"],
 "properties": {
 "business_template": {
 "type": "string",
 "description": "Bare directory name of the Business Template, e.g. erp5_project."
 },
 "expected_repository_revision": {
 "type": ["string", "null"],
 "default": "",
 "description": "Optional git object id (full or shortened) the caller expects HEAD to be at."
 },
 "expected_erp5_revision": {
 "type": ["string", "null"],
 "default": "",
 "description": "Optional installed Business Template revision the caller expects."
 },
 "path_pattern": {
 "default": null,
 "type": ["string", "array", "null"],
 "description": "Glob patterns (e.g. '*supply_line*') narrowing every comparison to matching paths; matched against repository-root-relative paths like bt5/erp5_core/CatalogMethodTemplateItem/..., and '*' spans '/'. Accepts a JSON array or newline/comma-separated entries. The cheap drift check for big templates."
 },
 "summary_only": {
 "default": null,
 "type": ["boolean", "integer", "null"],
 "description": "Return only counts for every path list (nothing is hidden silently: counts and '_more' markers say what was left out). Default (null): true is set automatically for templates with more than 500 files, whose full per-file sweeps are what timed the tool out."
 },
 "max_list": {
 "default": 25,
 "type": ["integer", "null"],
 "description": "Cap per returned list when summary_only is false."
 }
 }
 }
